const fs = require('fs');
const filePath = '/home/node/.n8n/bekleyen_mesajlar.json';

let mesajlar = [];

if (fs.existsSync(filePath)) {
  const content = fs.readFileSync(filePath, 'utf8').trim();
  if (content) {
    const lines = content.split('\n').filter(Boolean);
    mesajlar = lines.map(line => {
      try {
        return JSON.parse(line);
      } catch (e) {
        return { mesaj: line };
      }
    });
    fs.writeFileSync(filePath, '');
  }
}

const birlestirilmisMetin = mesajlar.map((m, idx) => `${idx + 1}. [${m.gonderen || 'Öğrenci'}]: ${m.mesaj}`).join('\n');

return [{
  json: {
    toplam_mesaj_sayisi: mesajlar.length,
    birlestirilmis_mesajlar: birlestirilmisMetin
  }
}];

const fs = require('fs');

let raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || 'Özet üretilemedi.';

// Mojibake Karakter Düzeltme (GBK/UTF8 Uyumsuzluğunu Onar)
const mojibakeMap = {
  '谋': 'ı', '枚': 'ö', '臒': 'ğ', '莽': 'ç', '艧': 'ş', '眉': 'ü',
  '陌': 'İ', '脰': 'Ö', '脟': 'Ç', '舰': 'Ş', '脺': 'Ü', '臑': 'Ğ',
  '馃搶': '📌'
};
raw = raw.replace(/[谋枚臒莽艧眉陌脰脟舰脺臑]|馃搶/g, m => mojibakeMap[m] || m);

const zaman = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

// Okunabilir HTML Raporu Hazırla
const htmlContent = `<!DOCTYPE html>
<html lang="tr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Öğretmen Ders Özeti Paneli</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0f172a; color: #f8fafc; margin: 0; padding: 2rem; }
    .card { max-width: 850px; margin: 0 auto; background: #1e293b; border-radius: 12px; padding: 2.5rem; box-shadow: 0 10px 30px rgba(0,0,0,0.5); border: 1px solid #334155; }
    h1 { color: #38bdf8; font-size: 1.8rem; margin-top: 0; }
    .badge { background: #0284c7; color: #fff; padding: 4px 12px; border-radius: 9999px; font-size: 0.85rem; font-weight: 600; }
    .time { color: #94a3b8; font-size: 0.9rem; margin-top: 0.5rem; }
    hr { border: none; border-top: 1px solid #334155; margin: 1.5rem 0; }
    .report { white-space: pre-wrap; font-size: 1.05rem; line-height: 1.7; color: #e2e8f0; }
  </style>
</head>
<body>
  <div class="card">
    <span class="badge">🎓 Öğretmen Asistanı</span>
    <h1>Son Öğrenci Soruları Özeti</h1>
    <div class="time">Rapor Tarihi: ${zaman}</div>
    <hr>
    <div class="report">${raw}</div>
  </div>
</body>
</html>`;

try {
  fs.writeFileSync('/home/node/.n8n/son_ogretmen_ozeti.html', htmlContent, 'utf8');
  fs.writeFileSync('/home/node/.n8n/son_ogretmen_ozeti.md', raw, 'utf8');
} catch (e) {}

return [{
  json: {
    durum: 'basarili',
    tarih: zaman,
    okunabilir_ozet: raw
  }
}];

